  namespace ascend = at::native::flagos::ascend;
  auto result_dtype = ascend::BinaryResultType("aclnnFmodTensor", self, other);
  auto self_c = self.scalar_type() == result_dtype
      ? self
      : self.to(self.options().dtype(result_dtype));
